using Newtonsoft.Json;

namespace Zentin.Payment.SDK.Models
{
    /// <summary>
    /// Payment order creation response entity class
    /// </summary>
    public class PayOrderCreateResModel : AgPayObject
    {
        /// <summary>
        /// Payment order number (generated by gateway)
        /// </summary>
        [JsonProperty("payOrderId")]
        public string PayOrderId { get; set; }

        /// <summary>
        /// Merchant order number (generated by merchant system)
        /// </summary>
        [JsonProperty("mchOrderNo")]
        public string MchOrderNo { get; set; }

        /// <summary>
        /// Order status
        /// 0-Order created
        /// 1-Paying
        /// 2-Payment successful
        /// 3-Payment failed
        /// 4-Cancelled
        /// 5-Refunded
        /// 6-Order closed
        /// </summary>
        [JsonProperty("orderState")]
        public int OrderState { get; set; }

        /// <summary>
        /// Payment parameter type
        /// </summary>
        [JsonProperty("payDataType")]
        public string PayDataType { get; set; }

        /// <summary>
        /// Payment parameters
        /// </summary>
        [JsonProperty("payData")]
        public string PayData { get; set; }

        /// <summary>
        /// Payment channel error code
        /// </summary>
        [JsonProperty("errCode")]
        public string ErrCode { get; set; }

        /// <summary>
        /// Payment channel error message
        /// </summary>
        [JsonProperty("errMsg")]
        public string ErrMsg { get; set; }
    }
}